def check_E(n):
    if n < 0:
        return False
    if 2 * n - 1 == 0:
        return False # Should not happen for integer n

    numerator = 3 * ((n + 2)**factorial(n + 2) + 1)
    denominator = 2 * n - 1

    result = numerator / denominator
    return result == int(result)

from math import factorial
solutions = []
for n in range(15): # Checking up to n=14
    if check_E(n):
        solutions.append(n)

print(solutions)
